mutation SubmitVillageCensusSnapshotV2(
        $villageId: Int!,
        $definitionVersionId: Int!,
        $occurrenceId: Int,
        $censusDate: Date!,
        $formData: GenericScalar!
      ) {
        submitVillageCensusSnapshotV2(
          villageId: $villageId,
          definitionVersionId: $definitionVersionId,
          occurrenceId: $occurrenceId,
          censusDate: $censusDate,
          formData: $formData
        ) {
          result {
            __typename
            ... on VillageCensusSnapshotType {
              id
              censusDate
              submittedAt
              roundResolution
              roundOccurrence {
                id
                occurrenceKey
                mode
              }
              villageHouseholdQuantity
              animalHouseholdQuantity
              village {
                id
                code
                name
              }
              facts {
                rowKey
                rowLabel
                animalQuantity
                householdQuantity
              }
            }
            ... on VillageCensusSnapshotProblem {
              fields {
                name
                message
              }
              message
            }
          }
        }
      }

